// Optional, offline CUE-DETR model output. Reports are per-source sidecars
// generated by scripts/automix-import-cues.mjs, never computed on the audio
// thread and never fetched from a playback URL.
const fs = require('fs')
const MAX_REPORT_BYTES = 128 * 1024
const SCHEMA = 'lokal-automix-advanced-v1'
const suffix = '.lokal-automix.json'
const finite = v => typeof v === 'number' && Number.isFinite(v)

function validateAdvancedReport(value, stat) {
  if (!value || value.schema !== SCHEMA || !value.source || !stat) return null
  const { size, mtimeMs } = value.source
  if (!Number.isSafeInteger(size) || size !== stat.size ||
      !finite(mtimeMs) || Math.abs(mtimeMs - stat.mtimeMs) > 1 ||
      !/^[a-f0-9]{64}$/.test(value.source.sha256 || '')) return null
  const duration = value.durationSeconds
  if (!finite(duration) || duration < 20 || duration > 7200) return null
  const bpm = value.bpm
  if (bpm != null && (!finite(bpm) || bpm < 50 || bpm > 220)) return null
  if (value.analyzer?.id !== 'disco-eth/cue-detr' ||
      typeof value.analyzer.revision !== 'string' ||
      value.analyzer.revision.length > 150) return null
  const cues = value.transitionCues
  if (!cues || !Array.isArray(cues.entrances) || !Array.isArray(cues.exits)) return null
  const parseCues = source => {
    if (source.length > 24) return null
    const valid = []
    for (const cue of source) {
      if (!cue || !finite(cue.time) || cue.time < 0 ||
          cue.time > duration || !finite(cue.confidence) ||
          cue.confidence < 0 || cue.confidence > 1) return null
      valid.push({ time: cue.time, confidence: cue.confidence, source: 'cue-detr' })
    }
    return valid
  }
  const entrances = parseCues(cues.entrances)
  const exits = parseCues(cues.exits)
  if (!entrances || !exits) return null
  return { duration, bpm, entrances, exits }
}

function readAdvancedReport(file, stat) {
  try {
    const sidecar = file + suffix
    if (fs.statSync(sidecar).size > MAX_REPORT_BYTES) return null
    const report = JSON.parse(fs.readFileSync(sidecar, 'utf8'))
    return validateAdvancedReport(report, stat)
  } catch { return null }
}

function mergeAdvancedAnalysis(analysis, report) {
  if (!analysis || !report ||
      Math.abs((analysis.duration || 0) - report.duration) > 2) return analysis
  // Preserve PCM-derived beat phase/tempo confidence. Cue reports are
  // role-specific but source-valid, so prefer their confirmed entry/exit
  // candidates while keeping conservative heuristic fallbacks.
  return {
    ...analysis,
    modelCueAnalysis: true,
    transitionCues: {
      entrances: [...report.entrances, ...(analysis.transitionCues?.entrances || [])].slice(0, 24),
      exits: [...report.exits, ...(analysis.transitionCues?.exits || [])].slice(0, 24),
    },
  }
}

module.exports = { SCHEMA, suffix, validateAdvancedReport, readAdvancedReport, mergeAdvancedAnalysis }
